# src/llm.pyfrom .provider import complete, LLMUnavailableFALLBACK = (    "Summary: see numeric checks.\n"    "- Improve the failing metric toward its threshold.\n"    "- Re-test under specified method settings.")def _grounded_specimen_prompt(standard_id, version, specimen_id, lot, checks_table: str):    system = "You are a compliance QA assistant. Use ONLY the provided results."    user = f"""Standard: {standard_id} v{version}Specimen: {specimen_id}; Lot: {lot}Checks:{checks_table}Write a short plain-text assessment, no headings, no bold, no markdown:First, one sentence stating pass or fail and naming the deciding metric with its measured value.Then two numbered remediation steps, each one sentence, referring to process or test parameters.Use plain hyphens, not dashes. Under 80 words total. Make no claim beyond the numbers above."""    return system, userdef explain_specimen(standard_id, version, specimen_id, lot, checks_table: str) -> str:    system, user = _grounded_specimen_prompt(        standard_id, version, specimen_id, lot, checks_table    )    try:        return complete(system, user, max_tokens=250, temperature=0.2)    except LLMUnavailable:        return FALLBACK